-- PASO 4: Actualizar referencias en tabla orders
-- ============================================================================
-- Mueve todos los pedidos de locations duplicadas al master

UPDATE orders o
INNER JOIN ConsolidacionMapping cm ON o.CustomerLocationId = cm.LocationDuplicadaID
SET o.CustomerLocationId = cm.LocationMasterID
WHERE o.Deleted IS NULL OR o.Deleted = 0;

-- Verificacion: contar pedidos actualizados
SELECT 
    'Pedidos migrados a masters' as Accion,
    COUNT(*) as Cantidad
FROM orders o
INNER JOIN ConsolidacionMapping cm ON o.CustomerLocationId = cm.LocationMasterID;

-- PASO 5: Actualizar referencias en tabla LogisticCode
-- ============================================================================
-- Mueve codigos logisticos de duplicadas al master (si no existen ya)

UPDATE LogisticCode lc
INNER JOIN ConsolidacionMapping cm ON lc.CustomerLocationId = cm.LocationDuplicadaID
SET lc.CustomerLocationId = cm.LocationMasterID
WHERE (lc.Deleted IS NULL OR lc.Deleted = 0)
  AND NOT EXISTS (
    SELECT 1 FROM LogisticCode lc2
    WHERE lc2.CustomerLocationId = cm.LocationMasterID
      AND lc2.MarketplaceDistributorId = lc.MarketplaceDistributorId
      AND lc2.Code = lc.Code
      AND (lc2.Deleted IS NULL OR lc2.Deleted = 0)
  );

-- Marcar como deleted los codigos duplicados que ya existen en el master
UPDATE LogisticCode lc
INNER JOIN ConsolidacionMapping cm ON lc.CustomerLocationId = cm.LocationDuplicadaID
SET lc.Deleted = 1
WHERE (lc.Deleted IS NULL OR lc.Deleted = 0)
  AND EXISTS (
    SELECT 1 FROM LogisticCode lc2
    WHERE lc2.CustomerLocationId = cm.LocationMasterID
      AND lc2.MarketplaceDistributorId = lc.MarketplaceDistributorId
      AND lc2.Code = lc.Code
      AND (lc2.Deleted IS NULL OR lc2.Deleted = 0)
  );

-- PASO 6: Actualizar referencias en tabla SalesRepCustomerLocations
-- ============================================================================

UPDATE SalesRepCustomerLocations src
INNER JOIN ConsolidacionMapping cm ON src.CustomerLocationId = cm.LocationDuplicadaID
SET src.CustomerLocationId = cm.LocationMasterID
WHERE src.Deleted IS NULL OR src.Deleted = 0;

-- PASO 7: Marcar locations duplicadas como deleted
-- ============================================================================
-- NO SE ELIMINAN fisicamente, solo se marcan como deleted para mantener
-- la trazabilidad y poder revertir si es necesario

UPDATE CustomerLocation cl
INNER JOIN ConsolidacionMapping cm ON cl.ID = cm.LocationDuplicadaID
SET 
    cl.Deleted = 1,
    cl.UpdatedDate = CURRENT_TIMESTAMP
WHERE cl.Deleted IS NULL OR cl.Deleted = 0;

