-- PASO 9: Reportes de verificacion
-- ============================================================================

-- Resumen de consolidacion
SELECT 
    'Grupos consolidados' as Metrica,
    COUNT(DISTINCT GrupoID) as Cantidad
FROM ConsolidacionMapping
UNION ALL
SELECT 
    'Locations duplicadas marcadas como deleted',
    COUNT(*)
FROM ConsolidacionMapping
UNION ALL
SELECT 
    'Locations master mantenidas',
    COUNT(DISTINCT LocationMasterID)
FROM ConsolidacionMapping;

-- Verificar que no haya pedidos huerfanos
SELECT COUNT(*) as PedidosHuerfanos
FROM orders o
LEFT JOIN CustomerLocation cl ON o.CustomerLocationId = cl.ID
WHERE cl.ID IS NULL
  AND (o.Deleted IS NULL OR o.Deleted = 0);

-- Locations activas antes y despues
SELECT 
    'Antes de consolidacion' as Estado,
    COUNT(*) as LocationsActivas
FROM CustomerLocation_Backup_20260302
WHERE Deleted IS NULL OR Deleted = 0
UNION ALL
SELECT 
    'Despues de consolidacion',
    COUNT(*)
FROM CustomerLocation
WHERE Deleted IS NULL OR Deleted = 0;

